// Decode the SIF buffer to UTF-8 text once for the parser. SIF
// is pipe-delimited ASCII; non-ASCII is a hard reject (CBUAE rule).
const item = items[0];
const bin = item.binary.sif;
if (!bin) throw new Error('SIF binary attachment missing');
const raw = Buffer.from(bin.data, 'base64');
const text = raw.toString('utf8');
// Reject non-printable / non-ASCII early — CBUAE SIF spec mandates
// 7-bit ASCII. Anything else means corruption or wrong-encoding upload.
for (let i = 0; i < text.length; i++) {
  const c = text.charCodeAt(i);
  if (c > 127 || (c < 32 && c !== 9 && c !== 10 && c !== 13)) {
    throw new Error(`Non-ASCII byte at offset ${i} (0x${c.toString(16)}) — CBUAE SIF requires 7-bit ASCII.`);
  }
}
return [{
  json: {
    ...item.json,
    fingerprint: item.json.fingerprint,
    byteLength: raw.length,
    sifText: text,
  },
  binary: item.binary,
}];

// CBUAE Universal Account framework pre-validation.
//
// Parses the SIF header (SCR — record type 1) + employee detail
// records (SEDR — record type 2). Pipe-delimited. Verifies the
// structural + regulatory invariants BEFORE the bulk POST so a
// malformed file never reaches the backend transactional path.
//
// CBUAE Universal Account rules enforced here:
//   • Employer EID is 14 digits (MOHRE register format).
//   • SCR salary cycle from ≤ cycle to.
//   • Currency code is AED (only AED-denominated WPS files are
//     accepted at the Phase-1 ingest gate).
//   • Every SEDR carries a 23-char UAE IBAN routing the wage to a
//     wage-receipt VEHICLE (bank account / SVF wallet / Universal
//     Account). A 16-digit card PAN in the routing column is a hard
//     reject — prepaid cards are no longer permitted as the WPS payee.
//   • SCR record count matches actual SEDR count.
//   • SCR total amount matches the SEDR amount sum (fils-precision).
//
// On any violation, throw with a structured error code so the
// downstream router moves the file to the rejected/ prefix and
// surfaces the precise CBUAE rule that fired.
const item = items[0];
const lines = item.json.sifText
  .split(/\r?\n/)
  .map((l) => l.trim())
  .filter((l) => l.length > 0);
if (lines.length === 0) throw new Error('SIF_EMPTY');

function parseLine(line, lineNo) {
  const parts = line.split('|');
  if (parts.length < 2) {
    const e = new Error(`SIF_MALFORMED_LINE@${lineNo}`);
    e.context = { lineNo, line };
    throw e;
  }
  return parts;
}

const header = parseLine(lines[0], 1);
if (header[0] !== '1') {
  const e = new Error('SIF_HEADER_NOT_SCR');
  e.context = { actualRecordType: header[0] };
  throw e;
}
// SCR layout: 1|employer_eid|file_creator_eid|file_creation_date|file_creation_time|cycle_from|cycle_to|salary_month|record_count|total_amount|currency
const [, employerEid, fileCreatorEid, fileDate, fileTime, cycleFrom, cycleTo, salaryMonth, recordCountStr, totalAmountStr, currency] = header;

if (!/^\d{14}$/.test(employerEid)) {
  const e = new Error('SIF_EMPLOYER_EID_INVALID');
  e.context = { employerEid };
  throw e;
}
if (currency !== 'AED') {
  const e = new Error('SIF_CURRENCY_NOT_AED');
  e.context = { currency };
  throw e;
}
if (!/^\d{8}$/.test(cycleFrom) || !/^\d{8}$/.test(cycleTo) || cycleFrom > cycleTo) {
  const e = new Error('SIF_CYCLE_DATES_INVALID');
  e.context = { cycleFrom, cycleTo };
  throw e;
}
const declaredCount = Number(recordCountStr);
const declaredTotal = Number(totalAmountStr);
if (!Number.isFinite(declaredCount) || declaredCount < 0) {
  throw new Error('SIF_RECORD_COUNT_INVALID');
}
if (!Number.isFinite(declaredTotal) || declaredTotal < 0) {
  throw new Error('SIF_TOTAL_AMOUNT_INVALID');
}

// Verify the expectedEmployerId guard — set by the company-config
// node if the bucket-side key carries an expected-employer hint.
const expectedEmployerId = item.json.expectedEmployerId;
if (expectedEmployerId && expectedEmployerId !== employerEid) {
  const e = new Error('SIF_EMPLOYER_EID_MISMATCH');
  e.context = { expected: expectedEmployerId, actual: employerEid };
  throw e;
}

let actualCount = 0;
let runningTotalFils = 0;
const sedrErrors = [];
for (let i = 1; i < lines.length; i++) {
  const r = parseLine(lines[i], i + 1);
  if (r[0] !== '2') continue; // future record types tolerated for forward-compat
  actualCount++;
  // SEDR layout: 2|employee_eid|routing_code|account_number|salary_amount|...
  const [, employeeEid, routingCode, accountNumber, salaryAmountStr] = r;
  if (!/^\d{14,15}$/.test(employeeEid)) {
    sedrErrors.push({ lineNo: i + 1, code: 'SEDR_EMPLOYEE_EID_INVALID', employeeEid });
    continue;
  }
  // CBUAE rule: account_number must be a 23-char UAE IBAN OR an
  // SVF wallet handle prefixed `SVF_`. A bare 16-digit card PAN
  // means someone is trying to route the wage payment into a
  // prepaid card — explicitly disallowed under the new framework.
  const isIBAN = /^AE\d{21}$/.test(accountNumber);
  const isSvfHandle = /^SVF_[A-Z0-9]{8,32}$/.test(accountNumber);
  const isCardPAN = /^\d{16}$/.test(accountNumber);
  if (isCardPAN) {
    sedrErrors.push({ lineNo: i + 1, code: 'WPS_INVALID_PREPAID_CARD_ROUTING', employeeEid });
    continue;
  }
  if (!isIBAN && !isSvfHandle) {
    sedrErrors.push({ lineNo: i + 1, code: 'SEDR_ROUTING_INVALID', employeeEid, accountNumber });
    continue;
  }
  const amt = Number(salaryAmountStr);
  if (!Number.isFinite(amt) || amt <= 0) {
    sedrErrors.push({ lineNo: i + 1, code: 'SEDR_SALARY_INVALID', employeeEid });
    continue;
  }
  // Track in fils (×100) to dodge IEEE-754 drift across thousands
  // of rows. The declared total is in AED with 2 d.p.
  runningTotalFils += Math.round(amt * 100);
  if (!routingCode || routingCode.trim() === '') {
    sedrErrors.push({ lineNo: i + 1, code: 'SEDR_ROUTING_CODE_MISSING', employeeEid });
  }
}

if (sedrErrors.length > 0) {
  const e = new Error('SIF_SEDR_VALIDATION_FAILED');
  e.context = { errorCount: sedrErrors.length, first10: sedrErrors.slice(0, 10) };
  throw e;
}
if (actualCount !== declaredCount) {
  const e = new Error('SIF_COUNT_MISMATCH');
  e.context = { declared: declaredCount, actual: actualCount };
  throw e;
}
const declaredTotalFils = Math.round(declaredTotal * 100);
if (runningTotalFils !== declaredTotalFils) {
  const e = new Error('SIF_TOTAL_MISMATCH');
  e.context = { declaredFils: declaredTotalFils, actualFils: runningTotalFils };
  throw e;
}

return [{
  json: {
    ...item.json,
    parsed: {
      employerEid,
      fileCreatorEid,
      fileDate,
      fileTime,
      cycleFrom,
      cycleTo,
      salaryMonth,
      recordCount: actualCount,
      totalAmountAed: declaredTotal,
      currency,
    },
  },
  binary: item.binary,
}];

// Resolve companyId from the S3 key. We allow either:
//   • `incoming/<companyId-uuid>/<yyyymm>.sif`
//   • `incoming/<employerEid-14digit>/<yyyymm>.sif`
//
// In the EID-keyed form, we look up companyId via the backend's
// companies-by-employerEid endpoint (admin-scoped). The UUID-keyed
// form is the fast path — production CI configures this layout.
const item = items[0];
const key = item.json.key || '';
const segments = key.split('/');
if (segments.length < 3 || segments[0] !== 'incoming') {
  throw new Error('SIF_KEY_LAYOUT_UNEXPECTED');
}
const routingSegment = segments[1];
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EID_RE = /^\d{14}$/;
let resolveMode;
if (UUID_RE.test(routingSegment)) {
  resolveMode = 'companyId';
} else if (EID_RE.test(routingSegment)) {
  resolveMode = 'employerEid';
} else {
  throw new Error('SIF_KEY_ROUTING_SEGMENT_UNRECOGNISED');
}
return [{
  json: {
    ...item.json,
    routingSegment,
    resolveMode,
    expectedEmployerId: resolveMode === 'employerEid' ? routingSegment : undefined,
  },
  binary: item.binary,
}];

// Merge the looked-up companyId back into the routing context.
const lookupItem = items[0];
return [{
  json: {
    ...lookupItem.json,
    companyId: lookupItem.json.companyId || lookupItem.json.id,
  },
  binary: lookupItem.binary,
}];

// UUID path — routingSegment IS the companyId.
const item = items[0];
return [{
  json: {
    ...item.json,
    companyId: item.json.routingSegment,
  },
  binary: item.binary,
}];
